TYPE GateState :
(
    IDLE    := 0,
    OPENING := 1,
    CLOSING := 2,
    FAULT   := 3
);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    prevOpenBtn   : BOOL := FALSE;
    prevCloseBtn  : BOOL := FALSE;
    prevBoth      : BOOL := FALSE;
    state         : GateState := IDLE;
    openRising    : BOOL;
    closeRising   : BOOL;
    bothRising    : BOOL;
END_VAR

    openRising  := openBtn AND NOT prevOpenBtn;
    closeRising := closeBtn AND NOT prevCloseBtn;
    bothRising  := (openBtn AND closeBtn) AND NOT prevBoth;

    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;
    prevBoth     := (openBtn AND closeBtn);

    CASE TO_INT(state) OF
        0: // IDLE
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;

            IF NOT bothRising THEN
                IF openRising AND NOT openLimit THEN
                    state   := OPENING;
                    motorUp := TRUE;
                ELSIF closeRising AND NOT closeLimit THEN
                    state    := CLOSING;
                    motorDown := TRUE;
                END_IF
            END_IF

        1: // OPENING
            motorUp   := TRUE;
            motorDown := FALSE;

            IF openLimit THEN
                state   := IDLE;
                motorUp := FALSE;
            ELSIF obstacle THEN
                state      := FAULT;
                motorUp    := FALSE;
                errorFlag  := TRUE;
            END_IF

        2: // CLOSING
            motorUp   := FALSE;
            motorDown := TRUE;

            IF closeLimit THEN
                state     := IDLE;
                motorDown := FALSE;
            ELSIF obstacle THEN
                state     := OPENING;
                motorDown := FALSE;
                motorUp   := TRUE;
            END_IF

        3: // FAULT
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;

            IF bothRising AND NOT obstacle THEN
                state     := IDLE;
                errorFlag := FALSE;
            END_IF
    END_CASE

END_FUNCTION_BLOCK
